int main() {
    int n, m, c0, d0;
    cin >> n >> m >> c0 >> d0;

    vector<int> a(m), b(m), c(m), d(m);
    for (int i = 0; i < m; i++) {
        cin >> a[i] >> b[i] >> c[i] >> d[i];
    }

    // dp[i][j] = max money using first i stuffings and j grams of dough
    // We'll use 1D DP for dough
    // dp[j] = max money with j grams of dough used

    vector<int> dp(n + 1, 0);

    // First, handle the plain buns (stuffing 0)
    // We can make any number of plain buns
    // For each amount of dough j, we can make at most j/c0 plain buns
    // But we need to combine with stuffed buns

    // Actually, let's think of it differently.
    // We have m stuffed bun types and 1 plain bun type.
    // Each stuffed bun type i can be made at most a[i]/b[i] times.
    // Plain buns can be made unlimited (limited by dough).

    // Let's do DP over the stuffed buns first, then add plain buns at the end.
    // dp[j] = max money from stuffed buns using exactly j grams of dough
    // Then for each j, we can add (n-j)/c0 plain buns.

    // Initialize dp with -infinity, except dp[0] = 0
    const int NEG_INF = -1000000000;
    vector<int> dp(n + 1, NEG_INF);
    dp[0] = 0;

    for (int i = 0; i < m; i++) {
        int maxCount = a[i] / b[i];
        // For this stuffing type, we can make 0 to maxCount buns
        // Each bun uses c[i] dough and gives d[i] money
        // This is a bounded knapsack problem
        // We can use the standard technique: for each item, iterate from high to low
        // But since we can use multiple copies, we need to handle it properly

        // Actually, for bounded knapsack where we can use up to maxCount copies of item i,
        // we can do: for j from n down to 0, for k from 1 to maxCount, if j + k*c[i] <= n
        // But that's O(n * maxCount) which could be up to 1000 * 100 = 100000 per item, total 10*100000 = 1000000, which is fine.

        // Alternatively, we can use the binary decomposition or just simple iteration.
        // Let's use simple iteration for clarity.

        vector<int> new_dp = dp; // copy current state
        for (int j = 0; j <= n; j++) {
            if (dp[j] == NEG_INF) continue;
            for (int k = 1; k <= maxCount; k++) {
                int newDough = j + k * c[i];
                if (newDough > n) break;
                new_dp[newDough] = max(new_dp[newDough], dp[j] + k * d[i]);
            }
        }
        dp = new_dp;
    }

    int maxMoney = 0;
    for (int j = 0; j <= n; j++) {
        if (dp[j] == NEG_INF) continue;
        int remainingDough = n - j;
        int plainBuns = remainingDough / c0;
        int totalMoney = dp[j] + plainBuns * d0;
        maxMoney = max(maxMoney, totalMoney);
    }

